			if (this.ws !== socket) {
				return;
			}
			console.log('[WebSocketManager] Disconnected:', event.code, event.reason);
			this.setState('disconnected');
			this.stats.last_disconnected_at = new Date();
			this.ws = null;

			if (this.intentionalDisconnect) {
				this.intentionalDisconnect = false;
				return;
			}

