	 * Disconnect from WebSocket server
	 */
	disconnect(): void {
		this.clearReconnectTimer();
		this.clearConnectionLostTimer();
		this.intentionalDisconnect = true;

		if (this.ws) {
			const socket = this.ws;
			this.ws = null;
			socket.close(1000, 'Client disconnect');
		}

		this.setState('disconnected');
	}

